/** Each catalog language's locale for numbers and plural forms (`languageFormatTag`). */
const FORMAT_TAGS: Readonly<Record<string, string>> = {
  en: "en-US",
  ar: "ar",
  de: "de",
  es: "es",
  fr: "fr",
  ja: "ja",
  ko: "ko",
  "pt-BR": "pt-BR",
  "zh-Hans": "zh-Hans",
  "zh-Hant": "zh-Hant",
  "en-XA": "en",
  "ar-XB": "ar",
};

/** The language the panel's frame document speaks, English with no document. */
function currentLanguage(): string {
  return (typeof document === "undefined" ? "" : document.documentElement.lang) || "en";
}

function formatNumber(value: number): string {
  return value.toLocaleString(FORMAT_TAGS[currentLanguage()] ?? "en-US");
}

function pluralCategory(
  count: number,
  locale = FORMAT_TAGS[currentLanguage()] ?? "en-US",
): Intl.LDMLPluralRule {
  return new Intl.PluralRules(locale).select(count);
}

